/**
 * Page 3: Final Celebration & Romantic Trigger Animation
 * Faithfully replicating the couple visualization from "Page 3 visualization video.mp4":
 * - Forehead kissing couple line-art composed of shimmering starlight particles
 * - Floating romantic heart next to the couple with rhythmic heartbeat pulse
 * - Diamond glitter sparkling along the couple's contours
 * - Ambient cosmic nebula glow & twinkling starfield
 * - Romantic heart fireworks & floating stardust aura
 * - Zero-scroll, zero-glitch isolated stage architecture
 */

let canvas = document.getElementById("stars");
let ctx = canvas ? canvas.getContext("2d") : null;

let width = window.innerWidth;
let height = window.innerHeight;

// --- Background Stars ---
let stars = [];
const STAR_COUNT = 150;

function resizeCanvas() {
    if (!canvas) {
        canvas = document.getElementById("stars");
        if (canvas) ctx = canvas.getContext("2d");
    }
    width = window.innerWidth;
    height = window.innerHeight;
    if (canvas) {
        canvas.width = width;
        canvas.height = height;
    }

    if (!isCelebrationActive) {
        stars = [];
        for (let i = 0; i < STAR_COUNT; i++) {
            stars.push({
                x: Math.random() * width,
                y: Math.random() * height,
                radius: Math.random() * 1.8 + 0.3,
                opacity: Math.random(),
                speed: Math.random() * 0.015 + 0.003
            });
        }
    }
}

// --- Music Auto-play on Interaction ---
let musicStarted = false;

function startBackgroundMusic() {
    if (musicStarted) return;
    const musicFrame = document.getElementById("musicFrame");
    if (!musicFrame) return;
    musicStarted = true;

    try {
        musicFrame.contentWindow.postMessage(
            JSON.stringify({
                event: "command",
                func: "playVideo",
                args: []
            }),
            "*"
        );
    } catch (e) {
        // Fallback if blocked
    }

    document.removeEventListener("click", startBackgroundMusic);
    document.removeEventListener("touchstart", startBackgroundMusic);
}

document.addEventListener("click", startBackgroundMusic);
document.addEventListener("touchstart", startBackgroundMusic);

// --- Floating Emoji Hearts (Gentle ambient) ---
function createHeart() {
    const heart = document.createElement("div");
    heart.className = "floating-heart";
    heart.textContent = ["❤️", "💗", "💕", "✨"][Math.floor(Math.random() * 4)];
    heart.style.left = Math.random() * 100 + "vw";
    heart.style.fontSize = (15 + Math.random() * 20) + "px";
    document.body.appendChild(heart);
    setTimeout(() => heart.remove(), 6000);
}

const heartInterval = setInterval(createHeart, 1200);

